messages.content:
Tool response:
Tool: find_assignments
Description: Find Assignments
Parameters:
    {
      "type": "object",
      "properties": {
        "course_code": {
          "type": "string",
          "description": "Course code like 'CS101'",
          "title": "Course Code"
        },
        "title": {
          "type": "string",
          "description": "Assignment title like 'Debugging Loops'",
          "title": "Title"
        }
      },
      "required": [
        "course_code",
        "title"
      ]
    }

Tool response:
Tool: update_assignment
Description: Update Assignment
Parameters:
    {
      "type": "object",
      "properties": {
        "assignment_id": {
          "type": "integer",
          "title": "Assignment Id",
          "description": ""
        },
        "deadline": {
          "type": "string",
          "title": "Deadline"
        },
        "allow_retries": {
          "type": "boolean",
          "title": "Allow Retries"
        },
        "max_retries": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "title": "Max Retries"
        }
      },
      "required": [
        "assignment_id",
        "deadline",
        "allow_retries"
      ]
    }

Tool response:
Tool: find_test_cases
Description: Find Test Cases
Parameters:
    {
      "type": "object",
      "properties": {
        "assignment_id": {
          "type": "integer",
          "description": "Internal ID of the assignment containing the test case",
          "title": "Assignment Id"
        },
        "name": {
          "type": "string",
          "description": "Name of the test case like 'test_off_by_one'",
          "title": "Name"
        }
      },
      "required": [
        "assignment_id",
        "name"
      ]
    }

Tool response:
Tool: create_test_case_feedback
Description: Create Test Case Feedback
Parameters:
    {
      "type": "object",
      "properties": {
        "test_case_id": {
          "type": "integer",
          "title": "Test Case Id"
        },
        "feedback_message": {
          "type": "string",
          "title": "Feedback Message"
        }
      },
      "required": [
        "test_case_id",
        "feedback_message"
      ]
    }
